            ["Sources.Threshold.LockSensibility"] = "\u62b1\u6b7b\u7075\u654f\u5ea6",
            ["Sources.Threshold.LockSensibility.Note"] = "\u4e0eSimHub\u81ea\u8eab\u7684\u201cLock sensitivity\u201d\u8bbe\u7f6e\u5b8c\u5168\u4e00\u81f4\uff080-100\uff0c\u9ed8\u8ba450\uff09\u3002\u6570\u503c\u8d8a\u9ad8\uff0c\u5bf9\u5f3a\u529b\u5239\u8f66\u7684\u54cd\u5e94\u8d8a\u5feb\uff0c\u4f46\u4e5f\u4f1a\u964d\u4f4e\u6570\u503c\u6240\u80fd\u8fbe\u5230\u7684\u6700\u9ad8\u5f3a\u5ea6\u2014\u2014\u53ea\u6709\u9ed8\u8ba4\u503c\uff0850\uff09\u624d\u80fd\u8fbe\u5230\u771f\u6b63\u7684\u6ee1\u5f3a\u5ea6\uff1b\u9ad8\u4e8e50\u7684\u6570\u503c\u662f\u7528\u9876\u7aef\u5f3a\u5ea6\u6362\u53d6\u66f4\u65e9\u7684\u54cd\u5e94\u3002",
            ["Sources.Threshold.Slip.Note"] = "\u6253\u6ed1\u5224\u5b9a\u4f1a\u4f18\u5148\u68c0\u67e5\u5239\u8f66\u9608\u503c\uff1a\u5982\u679c\u5239\u8f66\u8e0f\u677f\u8e29\u4e0b\u8d85\u8fc7\u5176\u81ea\u8eab\u9608\u503c\uff0c\u5219\u4f18\u5148\u751f\u6548\uff0c\u6253\u6ed1\u6570\u503c\u5c06\u4e0e\u62b1\u6b7b\u4f7f\u7528\u76f8\u540c\u7684\u5239\u8f66\u6570\u503c\u3002\u53ea\u6709\u5f53\u5239\u8f66\u4f4e\u4e8e\u5176\u9608\u503c\u65f6\uff0c\u624d\u4f1a\u68c0\u67e5\u6cb9\u95e8\u662f\u5426\u8d85\u8fc7\u5176\u81ea\u8eab\u9608\u503c\uff08\u5e76\u4e14\u4ec5\u5728\u79bb\u5408\u5668\u8e0f\u677f\u4f4e\u4e8e5%\u65f6\u2014\u2014\u8fd9\u662fSimHub\u81ea\u8eab\u56fa\u5b9a\u7684\u89c4\u5219\uff09\u3002\u4f4e\u4e8e\u76f8\u5e94\u9608\u503c\u65f6\uff0c\u8f66\u8f6e\u6253\u6ed1\u529f\u80fd\u5b8c\u5168\u4e0d\u751f\u6548\u2014\u2014\u65e0\u8bba\u4e0b\u65b9\u9009\u62e9\u54ea\u4e00\u79cd\u6570\u636e\u6e90\uff0cRaw \u548c Normalized \u6570\u503c\u90fd\u8bfb\u53d6\u4e3a 0\uff08\u5173\u4e8e ShakeIt \u7ec4\u5408\u7684\u8bf4\u660e\uff0c\u53c2\u89c1\u8f66\u8f6e\u62b1\u6b7b\u81ea\u8eab\u7684\u8bf4\u660e\uff09\u3002\u9ed8\u8ba4\u503c\uff1a\u5239\u8f66\u8e0f\u677f\u8e29\u4e0b100%\uff08\u610f\u5473\u7740\u53ea\u6709\u6cb9\u95e8\u8e0f\u677f\u8e29\u4e0b\u2014\u2014\u4e0e\u5176\u81ea\u8eab40%\u7684\u9ed8\u8ba4\u503c\u6bd4\u8f83\u2014\u2014\u624d\u4f1a\u89e6\u53d1\u8f66\u8f6e\u6253\u6ed1\uff09\u2014\u2014\u8fd9\u662f\u523b\u610f\u7684\u9009\u62e9\uff0c\u8ba9\u6253\u6ed1\u9ed8\u8ba4\u4ec5\u7531\u6cb9\u95e8\u89e6\u53d1\uff0c\u5373\u4fbfSimHub\u81ea\u8eab\u5185\u7f6e\u7684legacy\u7b97\u6cd5\u5bf9\u6253\u6ed1\u548c\u62b1\u6b7b\u4f7f\u7528\u5b8c\u5168\u76f8\u540c\u7684\u5239\u8f66\u5224\u5b9a\u3002\u5982\u679c\u4f60\u5e0c\u671b\u6253\u6ed1\u50cfSimHub\u81ea\u8eab\u7b97\u6cd5\u4ee5\u53ca\u8f66\u8f6e\u62b1\u6b7b\u90a3\u6837\u5bf9\u5239\u8f66\u505a\u51fa\u54cd\u5e94\uff0c\u53ef\u4ee5\u5c06\u5239\u8f66\u9608\u503c\u8c03\u4f4e\u81f320%\uff08\u4e0e\u8f66\u8f6e\u62b1\u6b7b\u81ea\u8eab\u7684\u9ed8\u8ba4\u503c\u76f8\u540c\uff09\u3002",
