            ["Curve.Lock.AnchorNote"] = "\u6bcf\u4e00\u884c\u7684\u542b\u4e49\u662f\u201c\u5f53\u62b1\u6b7b\u503c\u8fbe\u5230\u8fd9\u4e2a\u539f\u59cb\u503c\u65f6\uff0c\u53d1\u9001\u8fd9\u4e2a\u8f93\u51fa\u503c\u201d\u3002\u9ed8\u8ba4\u7684\u66f2\u7ebf\u9884\u8bbe\u53d1\u900930\u5bf9\u5e9410\u300160\u5bf9\u5e9430\u548c80\u5bf9\u5e9480\u2014\u2014\u8f7b\u5239\u8f66\u65f6\u51e0\u4e4e\u6ca1\u6709\u53cd\u9988\uff0c\u7406\u60f3\u533a\u95f4\u5185\u6709\u660e\u663e\u7684\u632f\u52a8\u63d0\u793a\uff0c\u63a5\u8fd1\u62b1\u6b7b\u65f6\u5219\u6025\u5267\u589e\u5f3a\u3002",
            ["Curve.Lock.StartPoint.Desc"] = "\u4f4e\u4e8e\u6b64\u503c\u4e0d\u4f1a\u4ea7\u751f\u4efb\u4f55\u8f93\u51fa\u3002\u5982\u679c\u8f7b\u5239\u8f66\u65f6\u632f\u52a8\u8fc7\u591a\uff0c\u53ef\u4ee5\u63d0\u9ad8\u6b64\u503c\u3002\u9ed8\u8ba4\u503c\u4e3a {0}\u3002",
            ["Curve.Lock.Slightly.Desc"] = "\u8f6e\u80ce\u521a\u521a\u8fdb\u5165\u5de5\u4f5c\u533a\u95f4\u2014\u2014\u4f4e\u4e8e\u6b64\u503c\u4ecd\u6709\u4f59\u91cf\uff0c\u9ad8\u4e8e\u6b64\u503c\u5219\u5f00\u59cb\u771f\u6b63\u5229\u7528\u6293\u5730\u529b\u3002\u5c06\u6b64\u503c\u8c03\u4f4e\u53ef\u4ee5\u5728\u6b63\u5e38\u3001\u8f7b\u67d4\u5239\u8f66\u65f6\u4e0d\u4ea7\u751f\u632f\u52a8\u3002",
