            ["Curve.Slip.Critical.Desc"] = "\u8f66\u8f6e\u6b63\u5904\u4e8e\u5373\u5c06\u6253\u6ed1\u7684\u8fb9\u7f18\u2014\u2014\u5c1a\u672a\u6253\u6ed1\uff0c\u4f46\u53ea\u5dee\u4e00\u6b65\u3002\u8bf7\u7acb\u5373\u677e\u5f00\u6cb9\u95e8\u3002",
            ["Curve.Slip.EndPoint.Desc"] = "\u8fbe\u5230\u6216\u8d85\u8fc7\u6b64\u503c\u65f6\uff0c\u8f66\u8f6e\u5df2\u5b8c\u5168\u6253\u6ed1\uff0c\u52a8\u529b\u6b63\u5728\u88ab\u6d6a\u8d39\u2014\u2014\u8f93\u51fa\u59cb\u7ec8\u4e3a\u6700\u5927\u5f3a\u5ea6\u3002\u9ed8\u8ba4\u503c\u4e3a {0}\u3002",
