            ["GForce.Sustain.Note"] = "\u5728\u6301\u7eed\u7684\u91cd\u5239\u8f66\u6216\u52a0\u901f\u4e0b\uff0c\u540e\u7eed\u7684\u632f\u52a8\u57ab\u4f1a\u4fdd\u6301\u8f83\u5f31\u7684\u632f\u52a8\uff0c\u800c\u4e0d\u662f\u5b8c\u5168\u6d88\u5931\uff0c\u4ece\u800c\u4f7f\u6574\u4f53\u611f\u89c9\u4fdd\u6301\u8fde\u8d2f\u3002\u9ed8\u8ba4\u503c\u6765\u81ea\u672c\u5f15\u64ce\u81ea\u8eab\u6a21\u578b\u7684\u63a8\u7b97\uff0c\u800c\u975e\u968f\u610f\u8bbe\u5b9a\u7684\u6570\u5b57\u2014\u20140%\u5c06\u8fd8\u539f\u4e3a\u539f\u5148\u201c\u9010\u6e10\u6d88\u5931\u201d\u7684\u8868\u73b0\u3002",
            ["GForce.Motion.Note"] = "\u5239\u8f66/\u52a0\u901f\u53cd\u9988\u4f1a\u7ecf\u8fc7\u4e09\u4e2a\u9636\u6bb5\u4f20\u9012\uff08\u5148\u662f\u8fdc\u7aef\u9707\u52a8\u57ab\uff0c\u518d\u5230\u4e2d\u95f4\u9707\u52a8\u57ab\uff0c\u6700\u540e\u5230\u6700\u9760\u8fd1\u53d7\u529b\u65b9\u5411\u7684\u9707\u52a8\u57ab\uff09\u624d\u4f1a\u7a33\u5b9a\u4e0b\u6765\u2014\u2014\u731b\u8e29\u8e0f\u677f\u4f1a\u5e26\u6765\u4e00\u6b21\u5feb\u901f\u800c\u5f3a\u70c8\u7684\u626b\u63a0\uff0c\u8f7b\u67d4\u7684\u53d8\u5316\u5219\u5e26\u6765\u7f13\u6162\u800c\u8f7b\u5fae\u7684\u626b\u63a0\u3002\u4f60\u6240\u4fdd\u6301\u7684\u7a33\u5b9a\u5f3a\u5ea6\uff08\u6bcf\u4e2a\u9707\u52a8\u57ab\u6700\u7ec8\u7a33\u5b9a\u5728\u4ec0\u4e48\u7a0b\u5ea6\uff09\u4e0e\u8fd9\u79cd\u201c\u79fb\u52a8\u611f\u201d\u662f\u5206\u5f00\u7684\u3002\u4ee5\u4e0b\u4e09\u4e2a\u53c2\u6570\u63a7\u5236\u8fd9\u79cd\u611f\u89c9\u2014\u2014\u5f3a\u5ea6\u54cd\u5e94\u65f6\u95f4\u8d8a\u5927\uff0c\u7a33\u5b9a\u540e\u7684\u611f\u89c9\u8d8a\u7f13\u6162\u5e73\u6ed1\uff1b\u626b\u63a0\u901f\u5ea6\u8d8a\u9ad8\uff0c\u7a81\u7136\u7684\u53d8\u5316\u4f20\u9012\u5f97\u8d8a\u5feb\u3002\u5982\u679c\u60f3\u8ba9\u6574\u4e2a\u626b\u63a0\u611f\u89c9\u66f4\u6162\uff0c\u53ef\u4ee5\u8c03\u4f4e\u626b\u63a0\u901f\u5ea6\uff08\u5b83\u4f1a\u8ba9\u611f\u89c9\u5728\u9707\u52a8\u57ab\u95f4\u4f20\u9012\u5f97\u66f4\u7f13\u6162\uff09\uff0c\u5e76\u8c03\u9ad8\u626b\u63a0\u5e73\u6ed1\u65f6\u95f4\uff08\u8ba9\u5b83\u66f4\u67d4\u548c\u5730\u6e10\u5165\uff0c\u800c\u4e0d\u662f\u7a81\u7136\u8df3\u53d8\uff09\u3002\u626b\u63a0\u901f\u5ea6\u672c\u8eab\u8bbe\u6709\u5185\u90e8\u4e0a\u9650\uff0c\u8d85\u8fc7\u67d0\u4e2a\u503c\u540e\u518d\u8c03\u9ad8\u4e5f\u4e0d\u4f1a\u8ba9\u626b\u63a0\u53d8\u5f97\u66f4\u5feb\u3002\u8c03\u9ad8\u626b\u63a0\u901f\u5ea6\u8fd8\u4f1a\u964d\u4f4e\u89e6\u53d1\u8fd9\u4e00\u4e0a\u9650\u6240\u9700\u7684\u53d8\u5316\u901f\u7387\uff0c\u8d85\u8fc7\u8fd9\u4e00\u70b9\u540e\uff0c\u8f7b\u67d4\u548c\u5267\u70c8\u7684\u8f93\u5165\u4f1a\u53d8\u5f97\u66f4\u76f8\u4f3